/*
 * A360253  Numbers for which the prime indices have lesser mean than the
 *          distinct prime indices.
 * https://oeis.org/A360253
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the n‑th integer for which the mean of the multiset of
 *            its prime indices is less than the mean of the distinct prime
 *            indices. The sequence is generated by a brute‑force search over
 *            the natural numbers using a sieve of smallest prime factors
 * Range:     u8 n <= 56, u16 n <= 56, u32 n <= 56, u64 n <= 56, u128 n <= 56,
 *            big any n
 * Helpers:   build_primes, build_spf
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include "../utils/build_spf.h"
#include "../utils/build_primes.h"

seq_t a(idx_t n)
{
    /* Static data required by the computation */
    static idx_t sieve_limit = 0;
    static idx_t *spf = NULL;
    static idx_t *prime_list = NULL;
    static size_t prime_count = 0;
    static idx_t *prime_index = NULL;  /* 1‑based index of prime p, 0 if p not prime */

    static seq_t *seq = NULL;          /* Sequence values */
    static size_t seq_cap   = 0;
    static size_t seq_size  = 0;

    /* ---------- initialise prime data (once) ---------- */
    if (sieve_limit == 0) {
        /* The chosen limit is large enough to generate at least 10 000 terms
           (the values are below one million). */
        sieve_limit = 2000000u;

        build_spf(sieve_limit, &spf);
        build_primes(sieve_limit, &prime_list, &prime_count);

        prime_index = (idx_t *)calloc((size_t)(sieve_limit + 1), sizeof(idx_t));
        for (size_t i = 0; i < prime_count; ++i) {
            idx_t p = prime_list[i];
            if (p <= sieve_limit)
                prime_index[p] = (idx_t)(i + 1);   /* 1‑based index */
        }
    }

    /* ---------- extend the sequence until it contains n terms ---------- */
    idx_t cand = seq_size == 0 ? 2u : (idx_t)(seq[seq_size - 1] + 1u);

    while (seq_size < (size_t)n) {
        /* Stop if candidate exceeds the sieve limit – not expected for n<=10000 */
        if (cand > sieve_limit) {
            /* In the unlikely event that the sieve is too small, abort */
            break;
        }

        /* Factorisation of cand using the spf array */
        idx_t x = cand;
        seq_t S1 = 0;  /* sum of (index * multiplicity) over all prime factors */
        seq_t T1 = 0;  /* sum of multiplicities (|multiset|) */
        seq_t S0 = 0;  /* sum of indices of distinct primes */
        idx_t  k  = 0;  /* number of distinct primes (size of distinct set) */

        while (x > 1u) {
            idx_t p   = spf[x];
            idx_t cnt = 0;
            while (x % p == 0u) {
                x /= p;
                ++cnt;
            }

            idx_t idxp = prime_index[p];      /* 1‑based prime index */
            S1 += (seq_t)idxp * (seq_t)cnt;
            T1 += (seq_t)cnt;
            S0 += (seq_t)idxp;
            ++k;
        }

        /* Check the required inequality: sum(index*mult)/k < sum(index)/T1 */
        if (S1 * (seq_t)k < S0 * T1) {
            /* Append cand to the sequence */
            if (seq_size + 1 > seq_cap) {
                size_t new_cap = seq_cap < 2 ? 2 : seq_cap * 2;
                seq = (seq_t *)realloc(seq, new_cap * sizeof(seq_t));
                seq_cap = new_cap;
            }
            seq[seq_size++] = (seq_t)cand;
        }

        ++cand;
    }

    return seq[(size_t)n - 1];
}
